-- 022: the Chairperson of the Executive Committee, with photograph and biography.
-- Only fills the position while it is still empty, so later edits in the admin are never overwritten.

UPDATE leaders SET
  name = 'Mr. Okot Francis',
  photo = 'assets/img/chairperson-okot.webp',
  bio = 'Mr. Okot Francis is a youth development and advocacy professional with eight years of institutional and field experience in humanitarian and post-conflict settings. He is the Chairperson of the Adolescents and Youth Reference Group under the Uganda UN Joint Adolescents and Youth Programme. In that role he coordinates youth voices across 13 UN agencies. He advises government and UN partners on programme design, district roll-out across eight districts, and youth-led monitoring and accountability.\n\nHe has co-created national programmes with the Government of Uganda and the UN. He led youth co-design for the SAY Plus+ sexual and reproductive health programme, contributed to the national youth empowerment programme review, and sits on the Phase II (2026–2030) review of the UN Joint Programme. He is also Uganda’s nominee to the Great Lakes regional situational analysis on Youth, Peace and Security.\n\nHis earlier work with Live Again Uganda included trauma healing and counselling in post-conflict communities. He also ran programmes for South Sudanese refugee women and youth, including those living with disabilities, in Lamwo.\n\nA former President of the Uganda National Students Association and Guild President of Gulu University, he now chairs the Gulu University Convocation and serves on the University Council. He holds a Bachelor of Development Studies from Gulu University and is pursuing a Master of Development Studies at Makerere University. He is a skilled public speaker and writer of policy drafts, concept notes and donor briefs. He speaks Luo and English fluently.'
WHERE organ = 'executive' AND title = 'Chairperson' AND (name IS NULL OR name = '');
